package cloud.gitwide.ampverse;

import android.app.*;
import android.widget.*;
import androidx.media3.common.MediaItem;
import java.util.*;
import org.json.*;

/** Explicit binding/review UI. Open editors own copies; polling never changes those drafts. */
final class PlaylistSyncUi {
    private static void error(Activity a,Exception e){Toast.makeText(a,e.getMessage()==null?"Playlist operation failed":e.getMessage(),Toast.LENGTH_LONG).show();}
    static void authorize(Activity a,String base,String password,String server,String library){
        new AlertDialog.Builder(a).setTitle("Enable saved-playlist sync?").setMessage("Use this authorized host for normal and Smart Playlists? Saved edits synchronize automatically while AMP Verse is running and after reopening. Phone metadata and current playback are not uploaded or replaced. The access code is encrypted in Android Keystore. Other discovered stations cannot change this binding.\n\n"+base).setPositiveButton("Enable",(d,n)->{java.util.concurrent.ExecutorService work=java.util.concurrent.Executors.newSingleThreadExecutor();work.execute(()->{try{PlaylistSync.enable(a,base,password,server,library);a.runOnUiThread(()->Toast.makeText(a,"Playlist sync enabled. Open Library → Playlists.",Toast.LENGTH_LONG).show());}catch(Exception e){a.runOnUiThread(()->error(a,e));}finally{work.shutdown();}});}).setNegativeButton("Cancel",null).show();
    }
    static void settings(Activity a){new AlertDialog.Builder(a).setTitle("Server playlist sync").setMessage(PlaylistSync.status+"\n\nConnect to a private Cast host, then choose Enable saved-playlist sync. Music mappings are explicit; missing songs remain in playlists. Deletion is not synchronized.").setPositiveButton("Check now",(d,n)->PlaylistSync.wake(a)).setNeutralButton("Pause",(d,n)->{try{PlaylistSync.pause(a);}catch(Exception e){error(a,e);}}).setNegativeButton("Close",null).show();}
    static void create(Activity a,boolean smart){EditText input=new EditText(a);input.setHint("Saved server playlist name");new AlertDialog.Builder(a).setTitle(smart?"New server Smart Playlist":"New server playlist").setView(input).setPositiveButton("Create",(d,n)->{try{String name=input.getText().toString().trim();if(name.isEmpty())throw new IllegalArgumentException("Enter a playlist name");PlaylistSync.create(a,smart,name);}catch(Exception e){error(a,e);}}).setNegativeButton("Cancel",null).show();}
    static void edit(Activity a,JSONObject list,Runnable play){
        try{JSONObject original=PlaylistSyncModel.copy(list),envelope=original.getJSONObject("_sync_envelope"),document=PlaylistSyncModel.copy(envelope.getJSONObject("document"));
            LinearLayout form=new LinearLayout(a);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(20,10,20,10);ScrollView scroll=new ScrollView(a);scroll.addView(form);EditText name=new EditText(a);name.setText(document.getString("name"));form.addView(name);
            TextView note=new TextView(a);note.setText("Saved server playlist · changes use its captured revision. Missing references remain saved. Current audio is unchanged.");form.addView(note);Button listen=new Button(a);listen.setText("Play mapped saved version");listen.setOnClickListener(v->play.run());form.addView(listen);
            if(envelope.getString("kind").equals("normal")){
                Button order=new Button(a);order.setText("Order / remove references");order.setOnClickListener(v->order(a,document));form.addView(order);
                Button add=new Button(a);add.setText("Add server song (duplicates allowed)");add.setOnClickListener(v->add(a,original,document));form.addView(add);
                Button map=new Button(a);map.setText("Match server songs to phone files");map.setOnClickListener(v->map(a,original));form.addView(map);
            }else{
                TextView rulesNote=new TextView(a);rulesNote.setText("Full server rules are retained. This editor changes name, style and target energy only. Source/filter editing remains on desktop/web. Local playback uses mapped eligible files, not the server's live running order.");form.addView(rulesNote);
                Spinner style=new Spinner(a);style.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"steady","hype","chill"}));style.setSelection(Arrays.asList("steady","hype","chill").indexOf(document.optString("style","steady")));form.addView(style);
                EditText energy=new EditText(a);energy.setHint("Target energy 1–10; blank = Auto");energy.setInputType(8194);energy.setText(document.isNull("target_energy")?"":String.valueOf(document.optDouble("target_energy")));form.addView(energy);
                form.setTag(new Object[]{style,energy});
                Button map=new Button(a);map.setText("Match server catalog to phone files");map.setOnClickListener(v->map(a,original));form.addView(map);
            }
            AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Edit synchronized playlist").setView(scroll).setPositiveButton("Save draft",null).setNeutralButton("Review conflict",(d,n)->review(a,original)).setNegativeButton("Cancel",null).create();
            dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String value=name.getText().toString().trim();if(value.isEmpty())throw new IllegalArgumentException("Enter a playlist name");document.put("name",value);if(envelope.getString("kind").equals("smart")){Object[] fields=(Object[])form.getTag();document.put("style",((Spinner)fields[0]).getSelectedItem().toString());String text=((EditText)fields[1]).getText().toString().trim();if(text.isEmpty())document.put("target_energy",JSONObject.NULL);else{double target=Double.parseDouble(text);if(!Double.isFinite(target)||target<1||target>10)throw new IllegalArgumentException("Energy must be 1–10");document.put("target_energy",target);}}PlaylistSync.saved(a,original,document);dialog.dismiss();}catch(Exception e){error(a,e);}}));dialog.show();
        }catch(Exception e){error(a,e);}
    }
    private static void order(Activity a,JSONObject document){try{JSONArray tracks=document.getJSONArray("tracks");String[] labels=new String[tracks.length()];for(int i=0;i<labels.length;i++)labels[i]=(i+1)+". "+tracks.getJSONObject(i).getString("relative_path");new AlertDialog.Builder(a).setTitle("All saved references, including missing files").setItems(labels,(d,n)->new AlertDialog.Builder(a).setItems(new String[]{"Move up","Move down","Remove reference"},(x,op)->{try{List<JSONObject> refs=new ArrayList<>();for(int i=0;i<tracks.length();i++)refs.add(tracks.getJSONObject(i));if(op==0&&n>0)Collections.swap(refs,n,n-1);if(op==1&&n+1<refs.size())Collections.swap(refs,n,n+1);if(op==2)refs.remove(n);document.put("tracks",new JSONArray(refs));order(a,document);}catch(Exception e){error(a,e);}}).show()).setNegativeButton("Done",null).show();}catch(Exception e){error(a,e);}}
    private static void add(Activity a,JSONObject list,JSONObject document){try{JSONObject catalog=PlaylistSync.stateFor(a,list).getJSONObject("catalog");List<String> ids=new ArrayList<>();Iterator<String> keys=catalog.keys();while(keys.hasNext())ids.add(keys.next());String[] names=new String[ids.size()];for(int i=0;i<names.length;i++)names[i]=catalog.getJSONObject(ids.get(i)).getString("relative_path");new AlertDialog.Builder(a).setTitle("Server catalog · first 2,000 entries").setItems(names,(d,n)->{try{JSONObject ref=PlaylistSyncModel.copy(catalog.getJSONObject(ids.get(n)));ref.remove("title");document.getJSONArray("tracks").put(ref);}catch(Exception e){error(a,e);}}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(a,e);}}
    private static void map(Activity a,JSONObject list){try{JSONObject state=PlaylistSync.stateFor(a,list),catalog=state.getJSONObject("catalog");JSONObject all=PlaylistSyncModel.copy(catalog);JSONObject v=list.getJSONObject("_sync_envelope");if(v.getString("kind").equals("normal")){JSONArray refs=v.getJSONObject("document").getJSONArray("tracks");for(int i=0;i<refs.length();i++){JSONObject ref=refs.getJSONObject(i);all.put(ref.getString("track_key"),ref);}}List<String> ids=new ArrayList<>();Iterator<String> keys=all.keys();while(keys.hasNext())ids.add(keys.next());String[] names=new String[ids.size()];for(int i=0;i<names.length;i++)names[i]=all.getJSONObject(ids.get(i)).getString("relative_path");new AlertDialog.Builder(a).setTitle("Choose a server reference").setItems(names,(d,n)->{List<MediaItem> media=PlaylistSync.media(a);String[] titles=new String[media.size()];for(int i=0;i<titles.length;i++)titles[i]=String.valueOf(media.get(i).mediaMetadata.title);new AlertDialog.Builder(a).setTitle("Explicitly match its phone file").setItems(titles,(x,j)->{try{PlaylistSync.map(a,list,ids.get(n),media.get(j).mediaId);Toast.makeText(a,"Phone mapping saved; source files unchanged",Toast.LENGTH_SHORT).show();}catch(Exception e){error(a,e);}}).setNegativeButton("Cancel",null).show();}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(a,e);}}
    private static void review(Activity a,JSONObject list){try{JSONObject s=PlaylistSync.stateFor(a,list),entry=s.getJSONObject("documents").getJSONObject(list.getJSONObject("_sync_envelope").getString("document_id"));if(!entry.has("blocked")){Toast.makeText(a,"No saved conflict for this playlist",Toast.LENGTH_LONG).show();return;}String current=entry.has("current")?entry.getJSONObject("current").getJSONObject("document").toString():"Unavailable";String desired=entry.has("desired")?entry.getJSONObject("desired").getJSONObject("document").toString():"Unavailable";new AlertDialog.Builder(a).setTitle("Review retained playlist versions").setMessage("Server:\n"+current+"\n\nSaved phone draft:\n"+desired+(entry.has("other_local_draft")?"\n\nOther retained phone draft:\n"+entry.getJSONObject("other_local_draft").getJSONObject("document").toString():"")+"\n\nKeeping the phone draft starts a NEW operation against this reviewed server revision. It does not retry an uncertain publication silently.").setPositiveButton("Use server",(d,n)->{try{PlaylistSync.review(a,list,true,entry.getJSONObject("current"));}catch(Exception e){error(a,e);}}).setNeutralButton("Keep reviewed phone draft",(d,n)->{try{PlaylistSync.review(a,list,false,entry.getJSONObject("current"));}catch(Exception e){error(a,e);}}).setNegativeButton("Later",null).show();}catch(Exception e){error(a,e);}}
}

